package com.screener.api.controller;
import com.screener.api.dto.CandidateDtos.*;import com.screener.api.dto.JobDtos.PageResponse;import com.screener.api.security.CurrentUser;import com.screener.api.service.CandidateService;import jakarta.validation.constraints.Max;import jakarta.validation.constraints.Min;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;
@Validated @RestController public class CandidateController {private final CandidateService service;public CandidateController(CandidateService service){this.service=service;}
 @GetMapping("/api/jobs/{id}/candidates") PageResponse<Candidate> list(@PathVariable String id,@RequestParam(defaultValue="score") String sort,@RequestParam(defaultValue="desc") String order,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size,@AuthenticationPrincipal CurrentUser u){return service.list(id,u.id(),sort,order,page,size);}
 @GetMapping("/api/candidates/{resumeId}") CandidateDetail detail(@PathVariable String resumeId,@AuthenticationPrincipal CurrentUser u){return service.detail(resumeId,u.id());}}
